import type { Live2DModelBindings } from "@/lib/avatar/live2d-avatar-provider";
import type { Live2DModelLayout } from "@/lib/avatar/model-layout";
import type { VoiceDeliveryMode } from "@/lib/voice/speech-chunks";

export type AgentMode = "hermes";
/** Audio is generated by the server-selected provider from config.json. */
export type VoiceMode = "configured";
export type AvatarMode = "live2d";
const STAGE_BACKGROUNDS = [
  "plain",
  "room",
  "pattern-sakura",
  "pattern-sparkle",
  "pattern-clouds",
  "pattern-seigaiha",
  "pattern-ribbon",
  "custom",
] as const;
export type StageBackground = (typeof STAGE_BACKGROUNDS)[number];

export function isStageBackground(value: unknown): value is StageBackground {
  return typeof value === "string"
    && (STAGE_BACKGROUNDS as readonly string[]).includes(value);
}
export type HostedAvatarModel = {
  id: string;
  name: string;
  url: string;
  addedAt: number;
};

/** The model Kana opens new conversations with; absent means Hermes's own. */
export type AgentModelChoice = {
  provider: string;
  model: string;
};

/**
 * Kana's own default for new conversations, per Hermes runtime identity
 * (`local` or an opaque `remote-…`). A default learned from one Hermes is
 * never sent to another, whose catalog may not contain that provider.
 */
export type AgentModelDefaults = Record<string, AgentModelChoice>;

/** The independently arrangeable desktop header widgets. */
export type HostWidgetId = "monitor" | "time" | "date";
export type HostWidgetZone = "left" | "center" | "right";
/** Widget ids per fixed header zone, in display order for that zone. */
export type HostWidgetLayout = Record<HostWidgetZone, HostWidgetId[]>;

export type KanaPreferences = {
  onboardingCompleted: boolean;
  /** Interface copy language; dictionary lives in lib/ui/copy.ts. */
  uiLocale: "id" | "en";
  agentMode: AgentMode;
  voiceEnabled: boolean;
  voiceMode: VoiceMode;
  avatarMode: AvatarMode;
  /** Off means a plain chat workspace: the stage, its pattern, and its canvas stay unmounted. */
  avatarVisible: boolean;
  /** Follow new chat entries; the feed's own switch writes it, not Settings. */
  autoScroll: boolean;
  /**
   * Kana's own default for new conversations, applied as a per-session Hermes
   * override at session.create. A runtime with no entry follows Hermes's
   * configured default.
   */
  agentModelDefaults: AgentModelDefaults;
  /**
   * How long the focus-mode composer holds its wide state after the draft,
   * focus, attachments, and dictation are gone, in seconds (0..600).
   */
  composerCollapseDelaySeconds: number;
  /**
   * Desktop avatar-mode chat panel width in pixels; 0 follows the standard
   * width. The panel clamps it to the current viewport.
   */
  chatPanelWidth: number;
  /** Zone and order of the desktop header widgets. */
  hostWidgetLayout: HostWidgetLayout;
  stageBackground: StageBackground;
  customBackgroundId?: string;
  hermes: {
    /** Working folder for the managed Hermes process (server-side concern). */
    cwd: string;
  };
  voice: {
    /** Kana voice library id; empty selects the bundled Kana voice. */
    voiceId: string;
    deliveryMode: VoiceDeliveryMode;
  };
  live2d: {
    modelUrl: string;
    modelId?: string;
    modelName?: string;
    coreScriptUrl: string;
    mouthOpenParameter: string;
    bindingProfiles?: Record<string, Live2DModelBindings>;
    layoutProfiles?: Record<string, Live2DModelLayout>;
    hostedModels?: HostedAvatarModel[];
  };
};

export interface PreferencesStore {
  load(): KanaPreferences;
  save(preferences: KanaPreferences): void;
}
